def kni(x, y):
	lst = []
	if x > 1 and y > 2:
		lst.append([x - 1, y - 2])
	if x < 8 and y > 2:
		lst.append([x + 1, y - 2])
	if x > 2 and y > 1:
		lst.append([x - 2, y - 1])
	if x < 7 and y > 1:
		lst.append([x + 2, y - 1])
	if x > 2 and y < 8:
		lst.append([x - 2, y + 1])
	if x < 7 and y < 8:
		lst.append([x + 2, y + 1])
	if x > 1 and y < 7:
		lst.append([x - 1, y + 2])
	if x < 8 and y < 7:
		lst.append([x + 1, y + 2])
	return lst
t = int(input())
while t > 0:
	f = 0
	(x1, y1) = map(int, input().split())
	(x2, y2) = map(int, input().split())
	p1 = kni(x1, y1)
	p2 = kni(x2, y2)
	for p in p1:
		if p in p2:
			f = 1
			break
	if f == 1:
		print('YES')
	else:
		print('NO')
	t -= 1
